  if (!str || typeof str !== 'string') return null;

  // Accept: "Mon, Sep 22 at 2:00pm PT[D]" or "Sep 22 at 2:00pm"
  const m = str.trim().match(/^(?:\w{3},\s*)?([A-Za-z]{3})\s+(\d{1,2})\s+at\s+(\d{1,2}):(\d{2})\s*(am|pm)\b/i);
  if (!m) return null;

  const mon = MONTH[m[1].toLowerCase()];
  const day = Number(m[2]);
  let hr = Number(m[3]);
  const min = Number(m[4]);
  const ampm = m[5].toLowerCase();

  if (ampm === 'pm' && hr !== 12) hr += 12;
  if (ampm === 'am' && hr === 12) hr = 0;

  // Choose a year: prefer any ISO on the item; else current year.
  const hintIso = $json.selected_iso || $json.window_min_iso || $json.window_max_iso || null;
  const year = hintIso ? new Date(hintIso).getUTCFullYear() : new Date().getFullYear();

  // Create "local wall time" and convert to the correct UTC instant for the TZ.
  const wallUTC = Date.UTC(year, mon, day, hr, min, 0);
  // Get the timezone offset (minutes) for that instant in the target TZ
  const tzLocal = new Date(new Date(wallUTC).toLocaleString('en-US', { timeZone: tz }));
  const offsetMin = Math.round((tzLocal.getTime() - wallUTC) / 60000);
  // Apply inverse offset to get real UTC instant
  const actualUTC = new Date(wallUTC - offsetMin * 60000);

  return actualUTC.toISOString();
}

function formatPT(iso, tz) {
  if (!iso || isNaN(Date.parse(iso))) return null;
  const d = new Date(iso);
  const s = d.toLocaleString('en-US', {
    timeZone: tz,
    weekday: 'short',
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
    timeZoneName: 'short',
  }).replace(/,/g, ''); // remove commas to avoid "Fri, Sep 19, at ..."
  const [wd, mo, day, time, ampm, tzname] = s.split(' ');
  return `${wd}, ${mo} ${day} at ${time.toLowerCase()}${ampm.toLowerCase()} ${tzname}`;
}

