// Build local datetime path: /YYYY-MM-DDTHH:mm:ss±HH:MM
function preselectPath(isoUtc, timezone) {
  const dUtc = new Date(isoUtc);

  const parts = Object.fromEntries(
    new Intl.DateTimeFormat('en-CA', {
      timeZone: timezone,
      year: 'numeric', month: '2-digit', day: '2-digit',
      hour: '2-digit', minute: '2-digit', second: '2-digit',
      hour12: false,
    })
    .formatToParts(dUtc)
    .map(p => [p.type, p.value])
  );

  const local = `${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}:${parts.second}`;

  const localDate = new Date(dUtc.toLocaleString('en-US', { timeZone: timezone }));
  const offsetMin = Math.round((localDate - new Date(dUtc.toISOString())) / 60000);
  const sign = offsetMin >= 0 ? '+' : '-';
  const hh = String(Math.floor(Math.abs(offsetMin) / 60)).padStart(2, '0');
  const mm = String(Math.abs(offsetMin) % 60).padStart(2, '0');

  return `${local}${sign}${hh}:${mm}`;
}

