//   - (optional) booking_url: event-level link if you want a fallback
//
// OUTPUT fields:
//   - more_time_1, more_time_2        (human labels)
//   - more_link_1, more_link_2        (URLs to book each slot)
//   - more_iso_1, more_iso_2          (ISO start times)
//   - sms_body                        (ready-to-send SMS text)
//   - has_two                          (boolean)

const tz = $json.timezone || 'America/Los_Angeles';
const slots = Array.isArray($json.next_two) ? $json.next_two : [];

function labelFromIso(iso) {
  if (!iso || isNaN(Date.parse(iso))) return null;
  // Matches your sheet style: "Mon, Sep 22 at 2:00pm PDT"
  const s = new Date(iso).toLocaleString('en-US', {
    timeZone: tz,
    weekday: 'short', month: 'short', day: 'numeric',
    hour: 'numeric', minute: '2-digit', hour12: true, timeZoneName: 'short',
  }).replace(/,/g, '');
  const [wd, mo, day, time, ampm, tzname] = s.split(' ');
  return `${wd}, ${mo} ${day} at ${time.toLowerCase()}${ampm.toLowerCase()} ${tzname}`;
}

function linkFor(slot) {
  // Prefer Calendly’s slot URL if provided by the availability API:
  if (slot?.raw?.scheduling_url) return slot.raw.scheduling_url;
  // Fallback to a generic booking page if you merged one earlier:
  if ($json.booking_url) return $json.booking_url;
  return null;
}

// Pull the first two (they should already be filtered)
const s1 = slots[0] || null;
const s2 = slots[1] || null;

// Build fields safely
const iso1 = s1?.iso || s1?.raw?.start_time || null;
const iso2 = s2?.iso || s2?.raw?.start_time || null;

const label1 = s1?.label || labelFromIso(iso1);
const label2 = s2?.label || labelFromIso(iso2);

const link1 = linkFor(s1);
const link2 = linkFor(s2);

const has1 = Boolean(iso1 && label1 && link1);
const has2 = Boolean(iso2 && label2 && link2);

let sms;
if (has1 && has2) {
  sms = `Here are two more options:\n1) ${label1} — ${link1}\n2) ${label2} — ${link2}\nReply 1 or 2 to choose.`;
} else if (has1) {
  sms = `I found another opening: ${label1} — ${link1}`;
} else {
  const fallback = $json.booking_url || '';
  sms = fallback
    ? `No additional slots right now. You can check the calendar here: ${fallback}`
    : `No additional slots right now.`;
}

return [{
  json: {
    ...$json,
    more_time_1: label1 || null,
    more_time_2: label2 || null,
    more_link_1: link1 || null,
    more_link_2: link2 || null,
    more_iso_1: iso1 || null,
    more_iso_2: iso2 || null,
    has_two: has1 && has2,
    sms_body: sms,
  }
}];

// Inputs on this merged item:
// - collection: Calendly slots (array from /event_type_available_times)
// - Any of these fields may exist with human strings: "Appointment 1", "Appointment 2",
//   "More Time 1", "More Time 2", "Time Selected", "Last Offered 1", "Last Offered 2"
// - Optional ISOs to exclude: selected_iso, start_iso
// - tz (optional) – default PT

const tz = $json.tz || 'America/Los_Angeles';

// --- helpers ---
function humanLabel(iso, timezone) {
  // e.g. "Mon, Sep 22 at 2:00pm PDT"
  const s = new Date(iso).toLocaleString('en-US', {
    timeZone: timezone,
    weekday: 'short', month: 'short', day: 'numeric',
    hour: 'numeric', minute: '2-digit', hour12: true, timeZoneName: 'short',
  }).replace(/,/g, ''); // remove commas to avoid double-comma issues
  const [wd, mo, day, time, ampm, tzname] = s.split(' ');
  return `${wd}, ${mo} ${day} at ${time.toLowerCase()}${ampm.toLowerCase()} ${tzname}`;
}

function normalizeLabel(s) {
  // Lowercase, remove commas/extra spaces, coalesce PDT/PST to PT
  if (!s) return '';
  return String(s)
    .toLowerCase()
    .replace(/,/g, '')
    .replace(/\s+/g, ' ')
    .replace(/\b(pdt|pst)\b/g, 'pt')
    .trim();
}

// --- build exclusion sets ---
const labelFields = [
  'Appointment 1', 'Appointment 2',
  'More Time 1', 'More Time 2',
  'Time Selected', 'Last Offered 1', 'Last Offered 2'
];

const excludeLabelSet = new Set(
  labelFields
    .map(k => ($json[k] || '').toString().trim())
    .filter(Boolean)
    .map(normalizeLabel)
);

const excludeIsoSet = new Set(
  [$json.selected_iso, $json.start_iso, $json.window_min_iso, $json.window_max_iso]
    .filter(v => v && !isNaN(Date.parse(v)))
);

// --- filter & pick next two ---
const slots = $json.collection || [];
const next_two = [];

for (const slot of slots) {
  const iso = slot.start_time || slot.start_time_utc || slot.start_time_iso;
  if (!iso || isNaN(Date.parse(iso))) continue;

  // Exclude if exact ISO was previously selected/offered
  if (excludeIsoSet.has(iso)) continue;

  const label = humanLabel(iso, tz);
  if (excludeLabelSet.has(normalizeLabel(label))) continue;

  next_two.push({ iso, label, raw: slot });
  if (next_two.length === 2) break;
}

return [{ json: { ...$json, next_two, timezone: tz } }];

// Calendly → extract core fields + pretty local time
// Inputs it supports:
//   - $json.payload... (already-parsed body), OR
//   - $json.body.payload... (Webhook node default)
// Outputs:
//   first_name, last_name, email, phone_raw, phone_e164,
//   text_consent_answer, text_consent_approved,
//   start_time_utc, start_time_pt_iso, start_time_pt_pretty

function getRoot(json) {
  if (json?.payload) return json;             // already flattened
  if (json?.body?.payload) return json.body;  // raw Webhook output
  return json;
}

function toE164(usLike) {
  if (!usLike) return null;
  const digits = String(usLike).replace(/\D+/g, '');
  if (!digits) return null;
  if (digits.length === 11 && digits.startsWith('1')) return `+1${digits.slice(1)}`;
  if (digits.length === 10) return `+1${digits}`;
  if (digits.startsWith('+')) return `+${digits.replace(/\D+/g, '')}`;
  return `+${digits}`;
}

function pickQA(qaArr, matcher) {
  if (!Array.isArray(qaArr)) return null;
  for (const qa of qaArr) {
    const q = (qa.question || '').toLowerCase();
    if (matcher(q)) return qa.answer || null;
  }
  return null;
}

function fmtStartTime(startIso, tz) {
  if (!startIso) return { ptIso: null, pretty: null };
  const date = new Date(startIso); // Calendly gives UTC ISO
  const timeZone = tz || 'America/Los_Angeles';

  // ISO in target TZ (not strictly ISO, but useful canonical string)
  // Build components with Intl to avoid DST math issues.
  const y = new Intl.DateTimeFormat('en-US', { timeZone, year: 'numeric' }).format(date);
  const m = new Intl.DateTimeFormat('en-US', { timeZone, month: '2-digit' }).format(date);
  const d = new Intl.DateTimeFormat('en-US', { timeZone, day: '2-digit' }).format(date);
  const hh = new Intl.DateTimeFormat('en-US', { timeZone, hour: '2-digit', hour12: false }).format(date);
  const mm = new Intl.DateTimeFormat('en-US', { timeZone, minute: '2-digit' }).format(date);
  const ptIso = `${y}-${m}-${d}T${hh}:${mm}:00`;

  // Pretty string like: "Tue, Sep 23 at 3:00 PM PDT"
  const wd = new Intl.DateTimeFormat('en-US', { timeZone, weekday: 'short' }).format(date);
  const mon = new Intl.DateTimeFormat('en-US', { timeZone, month: 'short' }).format(date);
  const dayNum = new Intl.DateTimeFormat('en-US', { timeZone, day: 'numeric' }).format(date);
  const hm = new Intl.DateTimeFormat('en-US', {
    timeZone,
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
  }).format(date);
  const tzShort = new Intl.DateTimeFormat('en-US', {
    timeZone,
    timeZoneName: 'short',
  }).format(date).split(' ').pop(); // usually "PDT"/"PST" (fallbacks to "GMT-7" in some envs)

  const pretty = `${wd}, ${mon} ${dayNum} at ${hm} ${tzShort}`;
  return { ptIso, pretty };
}

const root = getRoot($json);
const p = root.payload || {};

const firstName = p.first_name || null;
const lastName  = p.last_name  || null;
const email     = p.email      || null;

// Phone from Q&A (any question containing "phone" or "cell"); fallback: text_reminder_number
const phoneRaw = pickQA(p.questions_and_answers, q => q.includes('phone') || q.includes('cell'))
              || p.text_reminder_number
