return items.map(item => {
  const best = item.json; // Smarty returns a single object if you set "Always Output Array" = false

  // If you have multiple candidates, best could be an array. This handles both.
  const candidate = Array.isArray(best) ? best[0] : best;

  if (!candidate) {
    item.json.standardized = { street: "", city: "", state: "", zip: "", plus4: "" };
    item.json.address_ok = false;
    return item;
  }

  const street = candidate.delivery_line_1 || "";
  const comps = candidate.components || {};
  const city = comps.city_name || "";
  const state = comps.state_abbreviation || "";
  const zip = comps.zipcode || "";
  const plus4 = comps.plus4_code || "";

  const deliverable = candidate.analysis?.dpv_match_code === "Y";
  const needsUnit = candidate.analysis?.dpv_match_code === "D";

  item.json.standardized = { street, city, state, zip, plus4 };
  item.json.address_ok = deliverable && street && (zip || (city && state));
  item.json.needs_unit = needsUnit;
  item.json.candidate_count = Array.isArray(best) ? best.length : 1;

  return item;
});

return items.map(item => {
  const std = item.json.standardized || {};
  const city  = (std.city  || "").trim();
  const state = (std.state || "").trim();
  const zip   = (std.zip   || "").trim();

  // guard: need ZIP for both links
  if (!zip) {
    item.json.links = { zillow: null, zillow_alt: null, redfin: null };
    item.json.address_ok = false;
    item.json.missing = "zip";
    return item;
  }

  // Zillow (stable, ZIP-level "Recently Sold"; typically newest-first by default)
  const zillow = `https://www.zillow.com/homes/recently_sold/${encodeURIComponent(zip)}_rb/`;

  // Optional alternate Zillow link using a readable ZIP slug (no params)
  const slugify = (s) => s.toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
  const zillow_alt = (city && state)
    ? `https://www.zillow.com/${slugify(city)}-${slugify(state)}-${encodeURIComponent(zip)}/sold/`
    : zillow;

  // Redfin: ZIP-level, sold last year, newest sale date first
  const redfin = `https://www.redfin.com/zipcode/${encodeURIComponent(zip)}/filter/sort=hi-sale-date,include=sold-1yr`;

  item.json.links = { zillow, zillow_alt, redfin };
  item.json.address_ok = true;
  item.json.link_mode = "zip_recent_sold_newest";
  return item;
});

// Input item example:
// {
//   "slot1": {"start_time":"2025-09-18T18:00:00Z", "scheduling_url":"..."},
//   "slot2": {"start_time":"2025-09-18T18:30:00Z", "scheduling_url":"..."}
// }
// Output adds formatted_time_1 / formatted_time_2 like:
// "Thu, Sep 18 at 11:00am PT"

const TZ = 'America/Los_Angeles'; // change if needed

function formatPT(iso) {
  if (!iso) return null;
  const d = new Date(iso); // ISO in UTC or with offset

  const weekday = d.toLocaleDateString('en-US', {
    weekday: 'short',
    timeZone: TZ,
  });

  const monthDay = d.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    timeZone: TZ,
  });

  // "11:00 AM" -> "11:00am"
  const time = d.toLocaleTimeString('en-US', {
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
    timeZone: TZ,
  }).replace(' AM', 'am').replace(' PM', 'pm');

  return `${weekday}, ${monthDay} at ${time} PT`;
}

return items.map(item => {
  const row = { ...item.json };
  const t1 = row?.slot1?.start_time;
  const t2 = row?.slot2?.start_time;

  row.formatted_time_1 = formatPT(t1);
  row.formatted_time_2 = formatPT(t2);

  return { json: row };
});

