const digitsOnly = (v) => (v ?? '').toString().replace(/\D/g, '');
const last10 = (v) => digitsOnly(v).slice(-10);

return $input.all().map(item => {
  const r = item.json || {};

  // Prefer the sheet's "Phone"; fallbacks if you rename later
  const dest = last10(r['Phone'] ?? r['Customer Phone'] ?? r['Cell'] ?? r['PhoneTo'] ?? '');

  if (dest.length !== 10) {
    // Mark as skip-able; you can branch on _skip === true
    return { json: { _skip: true, _reason: 'Missing/invalid Phone', row_number: r.row_number ?? null, raw: r } };
  }

  // Optional contextual tags
  const leadId = r.row_number ?? r['Email'] ?? '';
  const source =
    (r['Buy or Sell?'] ? `Bob:${r['Buy or Sell?']}` : '') || DEFAULT_SOURCE;

  // If you ever want to override the campaign audio per-record,
  // add an "Audio URL" column in the sheet and uncomment below:
  const audioOverride = r['Audio URL'] ? String(r['Audio URL']).trim() : '';

  const payload = {
    CampaignToken: CAMPAIGN_TOKEN,
    PhoneTo: dest,               // 10 digits only
    AllowDuplicates: 'false',    // avoid re-dials within Drop’s window
    Source: source,
    C1: String(leadId)
  };

  if (audioOverride) payload.Audio = audioOverride; // must be public, ≤ 60s

  return { json: payload };
});

