// Pulls first 5-digit ZIP from the `body` field set by the previous node.
// Outputs standardized.zip and zip_for_links for your Zillow link builder.

return $input.all().map(item => {
  const j = item.json || {};
  const text = String(j.body ?? "");           // value from Set node

  const m = text.match(/\b\d{5}(?:-\d{4})?\b/);
  const zip = m ? m[0].slice(0, 5) : "";

  j.standardized = j.standardized || {};
  if (zip) j.standardized.zip = zip;

  j.zip_for_links = zip || "";

  // optional debug
  j._zip_debug = { text_len: text.length, zip, sample: text.slice(0, 120) };

  return { json: j };
